Add-Type -TypeDefinition 'using System; using System.Runtime.InteropServices; public class VT { [DllImport("kernel32.dll", SetLastError = true)] public static extern IntPtr GetStdHandle(int nStdHandle); [DllImport("kernel32.dll", SetLastError = true)] public static extern bool GetConsoleMode(IntPtr hConsoleHandle, out uint lpMode); [DllImport("kernel32.dll", SetLastError = true)] public static extern bool SetConsoleMode(IntPtr hConsoleHandle, uint dwMode); }'; $h = [VT]::GetStdHandle(-11); $m = 0; [VT]::GetConsoleMode($h, [ref]$m) | Out-Null; [VT]::SetConsoleMode($h, $m -bor 0x0004) | Out-Null; if ($args.Count -eq 0) { exit 1 }; $cmd = $args[0]; $cmdArgs = $args[1..($args.Count - 1)]; Start-Process -FilePath $cmd -ArgumentList $cmdArgs -Wait -NoNewWindow